                          <p className="text-xs font-black uppercase tracking-widest">Aucun retour enregistré</p>
                       </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default Retour;

